ROZE_JULY = '3771bd9adf6bb8b4b8cd83f66005b267efda2803ce4283d80e8aff080215dda1'
_ROZE_AUGUST = '4667fa73d9c796d68636de5f043091560b247a479bbdad3105cced669177d03a'
# Independently compared complete normalized tables, including spans and headers.
# Only physical table positions differ. The July archive is qualified separately.
REVIEWED[ROZE_JULY] = dict(
    cik=REVIEWED[_ROZE_AUGUST]['cik'], evidence=REVIEWED[_ROZE_AUGUST]['evidence'],
    tables={new: REVIEWED[_ROZE_AUGUST]['tables'][old]
            for old, new in ((585, 567), (587, 569), (591, 573))})


def plan_for(document_hash, cik):
    review = REVIEWED.get(document_hash)
    if review is None or str(int(cik)).zfill(10) != review['cik']:
        return None
    facts = []
    for table, spec in review['tables'].items():
        for row, tag, label, start, end, unit, decimals, value, columns in spec['facts']:
            facts.append(dict(concept='{https://xbrl.ifrs.org/taxonomy/2025-03-27/ifrs-full}' + tag,
                period_start=start, period_end=end, unit=unit, scale=0,
                decimals=decimals, expected_value=value, label=label, evidence=review['evidence'],
                table_proof=dict(heading=spec['heading'], headers=spec['headers']),
                locator=dict(kind='cells', table=table, row=row, label_column=0, columns=columns)))
    body = dict(version=VERSION, document_hash=document_hash, cik=review['cik'], scope='reviewed_observations', facts=facts)
    return dict(body, plan_hash=digest(body))
